import{_ as a,o as l,c as i,ae as o}from"./chunks/framework.RRduUuAx.js";const h=JSON.parse('{"title":"Local AWS-Equivalent BOM","description":"","frontmatter":{},"headers":[],"relativePath":"sessions/20260226-helios-market-research/16_LOCAL_AWS_EQUIVALENT_BOM.md","filePath":"sessions/20260226-helios-market-research/16_LOCAL_AWS_EQUIVALENT_BOM.md"}'),t={name:"sessions/20260226-helios-market-research/16_LOCAL_AWS_EQUIVALENT_BOM.md"};function r(s,e,n,c,d,p){return l(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="local-aws-equivalent-bom" tabindex="-1">Local AWS-Equivalent BOM <a class="header-anchor" href="#local-aws-equivalent-bom" aria-label="Permalink to &quot;Local AWS-Equivalent BOM&quot;">​</a></h1><p>Date: 2026-02-26 Scope: Local-first infrastructure bill of materials for Helios and related repos.</p><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>Provide a concrete &quot;local cloud&quot; module set that maps to common AWS/SaaS capabilities, with adoption priority and rollout phases.</p><h2 id="_1-must-have-phase-0-1" tabindex="-1">1) Must-Have (Phase 0-1) <a class="header-anchor" href="#_1-must-have-phase-0-1" aria-label="Permalink to &quot;1) Must-Have (Phase 0-1)&quot;">​</a></h2><ul><li><p><code>ElectroBun</code>:</p><ul><li>desktop shell runtime for Helios UI</li></ul></li><li><p><code>par</code> + <code>zellij</code> + <code>zmx</code> + <code>upterm</code> + <code>tmate</code>:</p><ul><li>worktree lanes, mux sessions, durability, and share/handoff</li></ul></li><li><p><code>Postgres</code> (with extensions):</p><ul><li>canonical relational system of record</li><li>suggested extensions: <code>pgvector</code>, time-series extension as needed</li></ul></li><li><p><code>SQLite/libSQL</code>:</p><ul><li>on-device edge/session state and fast local persistence</li></ul></li><li><p><code>Temporal</code>:</p><ul><li>durable long-running workflows, retries, approvals, resumability</li></ul></li><li><p><code>NATS JetStream</code>:</p><ul><li>event backbone, replay, KV/object primitives for operational state fanout</li></ul></li><li><p><code>OpenTelemetry</code> + <code>Prometheus</code> + <code>Loki</code> + <code>Grafana</code>:</p><ul><li>production-grade local observability and debugging</li></ul></li></ul><h2 id="_2-should-have-phase-2" tabindex="-1">2) Should-Have (Phase 2) <a class="header-anchor" href="#_2-should-have-phase-2" aria-label="Permalink to &quot;2) Should-Have (Phase 2)&quot;">​</a></h2><ul><li><p><code>Dapr</code>:</p><ul><li>service invocation and pubsub portability across local/distributed deployment targets</li><li>apply at service boundaries, not PTY hot path</li></ul></li><li><p><code>Valkey</code> (or <code>Dragonfly</code>):</p><ul><li>Redis-compatible hot cache plane where JetStream KV is not enough</li></ul></li><li><p><code>MinIO</code> or <code>SeaweedFS</code>:</p><ul><li>local S3-compatible object storage for artifacts/snapshots/exports</li></ul></li><li><p><code>Neo4j</code>:</p><ul><li>graph plane for relationship-heavy traversal and impact analysis (if needed)</li></ul></li></ul><h2 id="_3-optional-phase-3" tabindex="-1">3) Optional (Phase 3) <a class="header-anchor" href="#_3-optional-phase-3" aria-label="Permalink to &quot;3) Optional (Phase 3)&quot;">​</a></h2><ul><li><p><code>LocalStack</code>:</p><ul><li>local emulation for AWS API compatibility testing</li></ul></li><li><p><code>k3s</code>:</p><ul><li>laptop Kubernetes for microservice orchestration and production-like deployment drills</li></ul></li><li><p><code>OpenBao</code>:</p><ul><li>advanced secrets management parity with Vault-like workflows</li></ul></li><li><p><code>DuckDB</code>:</p><ul><li>local analytics acceleration for large event/audit exports</li></ul></li></ul><h2 id="_4-aws-saas-capability-mapping" tabindex="-1">4) AWS/SaaS Capability Mapping <a class="header-anchor" href="#_4-aws-saas-capability-mapping" aria-label="Permalink to &quot;4) AWS/SaaS Capability Mapping&quot;">​</a></h2><ul><li><p>Compute orchestration:</p><ul><li>AWS ECS/EKS equivalent -&gt; <code>k3s</code> + <code>Dapr</code> + process supervision</li></ul></li><li><p>Workflow orchestration:</p><ul><li>AWS Step Functions equivalent -&gt; <code>Temporal</code></li></ul></li><li><p>Event bus/streaming:</p><ul><li>AWS SNS/SQS/Kinesis equivalents -&gt; <code>NATS JetStream</code></li></ul></li><li><p>Key-value/cache:</p><ul><li>AWS ElastiCache equivalent -&gt; <code>Valkey</code>/<code>Dragonfly</code></li></ul></li><li><p>Object storage:</p><ul><li>AWS S3 equivalent -&gt; <code>MinIO</code> or <code>SeaweedFS</code></li></ul></li><li><p>Relational DB:</p><ul><li>AWS RDS Postgres equivalent -&gt; local <code>Postgres</code></li></ul></li><li><p>Graph DB:</p><ul><li>AWS Neptune-like graph capability -&gt; <code>Neo4j</code></li></ul></li><li><p>Secrets:</p><ul><li>AWS Secrets Manager equivalent -&gt; <code>OpenBao</code></li></ul></li><li><p>Observability:</p><ul><li>CloudWatch/X-Ray-like stack -&gt; <code>OTel + Prometheus + Loki + Grafana (+ Tempo/Jaeger)</code></li></ul></li></ul><h2 id="_5-phase-0-3-adoption-order" tabindex="-1">5) Phase 0-3 Adoption Order <a class="header-anchor" href="#_5-phase-0-3-adoption-order" aria-label="Permalink to &quot;5) Phase 0-3 Adoption Order&quot;">​</a></h2><h3 id="phase-0-contract-and-baseline" tabindex="-1">Phase 0: Contract and baseline <a class="header-anchor" href="#phase-0-contract-and-baseline" aria-label="Permalink to &quot;Phase 0: Contract and baseline&quot;">​</a></h3><ol><li>Postgres + SQLite/libSQL</li><li>Temporal</li><li>NATS JetStream</li><li>OTel/Grafana stack</li></ol><p>Exit:</p><ul><li>core local workflows run end-to-end with auditable events</li></ul><h3 id="phase-1-runtime-and-swarm-operations" tabindex="-1">Phase 1: Runtime and swarm operations <a class="header-anchor" href="#phase-1-runtime-and-swarm-operations" aria-label="Permalink to &quot;Phase 1: Runtime and swarm operations&quot;">​</a></h3><ol><li>par + zellij + zmx + upterm + tmate integrations fully wired</li><li>localbus + ACP/MCP/A2A boundaries stabilized</li></ol><p>Exit:</p><ul><li>25-terminal local swarm baseline stable</li></ul><h3 id="phase-2-portability-and-service-expansion" tabindex="-1">Phase 2: Portability and service expansion <a class="header-anchor" href="#phase-2-portability-and-service-expansion" aria-label="Permalink to &quot;Phase 2: Portability and service expansion&quot;">​</a></h3><ol><li>Dapr at selected service boundaries</li><li>Valkey/Dragonfly hot cache where needed</li><li>MinIO/SeaweedFS object storage</li></ol><p>Exit:</p><ul><li>distributed-ready architecture without hot-path regressions</li></ul><h3 id="phase-3-advanced-platform-parity" tabindex="-1">Phase 3: Advanced platform parity <a class="header-anchor" href="#phase-3-advanced-platform-parity" aria-label="Permalink to &quot;Phase 3: Advanced platform parity&quot;">​</a></h3><ol><li>k3s-based deployment topology</li><li>LocalStack for AWS compatibility simulations</li><li>OpenBao secrets hardening</li><li>optional Neo4j and DuckDB if justified by workload</li></ol><p>Exit:</p><ul><li>&quot;local cloud&quot; parity for multi-tenant MAS operations</li></ul><h2 id="_6-decision-rules" tabindex="-1">6) Decision Rules <a class="header-anchor" href="#_6-decision-rules" aria-label="Permalink to &quot;6) Decision Rules&quot;">​</a></h2><ol><li>Do not add distributed runtime components to PTY hot path.</li><li>Add modules only when they close a measured gap.</li><li>Every new module requires:</li></ol><ul><li>owner</li><li>rollback path</li><li>perf and operational acceptance checks</li></ul><h2 id="_7-minimal-starter-profile-recommended-now" tabindex="-1">7) Minimal Starter Profile (recommended now) <a class="header-anchor" href="#_7-minimal-starter-profile-recommended-now" aria-label="Permalink to &quot;7) Minimal Starter Profile (recommended now)&quot;">​</a></h2><ul><li>ElectroBun</li><li>Postgres + SQLite/libSQL</li><li>Temporal</li><li>NATS JetStream</li><li>par + zellij + zmx + upterm + tmate</li><li>OTel/Grafana stack</li></ul><p>Then layer Dapr and cache/object systems once real workload pressure proves need.</p>',35)])])}const m=a(t,[["render",r]]);export{h as __pageData,m as default};
